CREATE TABLE IF NOT EXISTS "SincronizacaoRecebidasSba" ("empresaFiscalId" INTEGER PRIMARY KEY REFERENCES "EmpresaFiscal"("empresafiscalid"),"empresaId" INTEGER NOT NULL REFERENCES "Empresa"("empresaid"),nsu BIGINT NOT NULL DEFAULT 0,"proximaConsulta" TIMESTAMP(3),"leaseAte" TIMESTAMP(3),"leaseToken" TEXT,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS "DocumentoRecebidoSba" ("empresaId" INTEGER NOT NULL REFERENCES "Empresa"("empresaid"),"empresaFiscalId" INTEGER NOT NULL REFERENCES "EmpresaFiscal"("empresafiscalid"),chave TEXT NOT NULL,nsu BIGINT NOT NULL,dados JSONB NOT NULL,PRIMARY KEY ("empresaFiscalId",chave));
CREATE INDEX IF NOT EXISTS "DocumentoRecebidoSba_empresa_nsu_idx" ON "DocumentoRecebidoSba"("empresaId","empresaFiscalId",nsu);
